window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-lang-sa-sanskrit-sectional-test-mtsa4hgc","subject":"lang-sa","day":62,"level":1,"title":"Sanskrit Language & Literature","hi":"संस्कृत भाषा एवं साहित्य","concepts":[{"title":"Introduction to Sanskrit Literature and Grammar","title_hi":"संस्कृत साहित्य एवं व्याकरण का परिचय","simple":"Sanskrit is an ancient language of India, and we learn about its famous books, poets, and grammar rules.","simple_hi":"संस्कृत भारत की प्राचीन भाषा है, और हम इसकी प्रसिद्ध पुस्तकों, कवियों और व्याकरण के नियमों के बारे में सीखते हैं।","intro":"","points":["संस्कृत विश्व की सबसे प्राचीन भाषाओं में से एक है, जिसे 'देवभाषा' भी कहा जाता है। / Sanskrit is one of the oldest languages, also called 'Devabhasha'.","वेद, रामायण, महाभारत जैसे महान ग्रंथ संस्कृत में लिखे गए हैं। / The Vedas, Ramayana, Mahabharata are written in Sanskrit.","पाणिनि ने 'अष्टाध्यायी' नामक व्याकरण ग्रंथ लिखा। / Panini wrote the grammar book 'Ashtadhyayi'.","कालिदास महान कवि थे, उन्होंने 'अभिज्ञानशाकुन्तलम्' लिखा। / Kalidasa was a great poet, he wrote 'Abhijnanasakuntalam'.","संस्कृत वर्णमाला में ५० वर्ण होते हैं। / Sanskrit alphabet has 50 letters.","संस्कृत भारत की शास्त्रीय भाषा है। / Sanskrit is a classical language of India."],"example":"जैसे हम हिंदी में 'राम' कहते हैं, वैसे ही संस्कृत में भी 'राम' शब्द है। संस्कृत व्याकरण में संज्ञा के तीन लिंग होते हैं - पुल्लिंग, स्त्रीलिंग, नपुंसकलिंग। जैसे 'बालक' (पुल्लिंग), 'बालिका' (स्त्रीलिंग), 'फल' (नपुंसकलिंग)। / Just as we say 'Ram' in Hindi, in Sanskrit also 'Rama' is a word. In Sanskrit grammar, nouns have three genders - masculine, feminine, neuter. For example, 'balaka' (masculine), 'balika' (feminine), 'phala' (neuter).","trick":"याद रखें: 'पाणिनि ने पाणि (हाथ) से अष्टाध्यायी लिखी' - पाणिनि का नाम 'पाणि' (हाथ) से जुड़ा है, और उन्होंने 8 अध्यायों में व्याकरण लिखा। / Remember: 'Panini wrote Ashtadhyayi with his hand (pani)' - Panini's name is linked to 'pani' (hand), and he wrote grammar in 8 chapters.","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"संस्कृत साहित्य का इतिहास वैदिक काल से आरम्भ होता है। वेद चार हैं - ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद। रामायण के रचयिता वाल्मीकि हैं, जिन्हें 'आदिकवि' कहा जाता है। महाभारत के रचयिता वेदव्यास हैं। कालिदास को 'कविकुलगुरु' कहा जाता है। व्याकरण में पाणिनि का स्थान सर्वोपरि है, उन्होंने 3998 सूत्रों में संस्कृत व्याकरण का विधिवत वर्णन किया। परीक्षा में प्रायः इन्हीं तथ्यों पर प्रश्न पूछे जाते हैं। / The history of Sanskrit literature begins from the Vedic period. There are four Vedas - Rigveda, Yajurveda, Samaveda, Atharvaveda. Valmiki is the author of Ramayana, known as 'Adikavi'. Vedavyasa is the author of Mahabharata. Kalidasa is called 'Kavikulaguru'. In grammar, Panini is supreme; he described Sanskrit grammar in 3998 sutras. Questions in exams are often based on these facts.","body_hi":"संस्कृत साहित्य का इतिहास वैदिक काल से आरम्भ होता है। वेद चार हैं - ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद। रामायण के रचयिता वाल्मीकि हैं, जिन्हें 'आदिकवि' कहा जाता है। महाभारत के रचयिता वेदव्यास हैं। कालिदास को 'कविकुलगुरु' कहा जाता है। व्याकरण में पाणिनि का स्थान सर्वोपरि है, उन्होंने 3998 सूत्रों में संस्कृत व्याकरण का विधिवत वर्णन किया। परीक्षा में प्रायः इन्हीं तथ्यों पर प्रश्न पूछे जाते हैं। / The history of Sanskrit literature begins from the Vedic period. There are four Vedas - Rigveda, Yajurveda, Samaveda, Atharvaveda. Valmiki is the author of Ramayana, known as 'Adikavi'. Vedavyasa is the author of Mahabharata. Kalidasa is called 'Kavikulaguru'. In grammar, Panini is supreme; he described Sanskrit grammar in 3998 sutras. Questions in exams are often based on these facts."}}],"questions":[{"q":"Who is the author of 'Ashtadhyayi'?","q_hi":"'अष्टाध्यायी' के रचयिता कौन हैं?","o":["Kalidasa","Panini","Valmiki","Vedavyasa"],"o_hi":["कालिदास","पाणिनि","वाल्मीकि","वेदव्यास"],"a":1,"exp":"Panini wrote the Ashtadhyayi, a foundational text of Sanskrit grammar.","exp_hi":"पाणिनि ने अष्टाध्यायी की रचना की, जो संस्कृत व्याकरण का आधारभूत ग्रंथ है।","why":["कालिदास एक महान कवि थे, उन्होंने नाटक और काव्य लिखे, व्याकरण नहीं।","वाल्मीकि ने रामायण की रचना की, वे व्याकरणाचार्य नहीं थे।","वेदव्यास ने महाभारत की रचना की, व्याकरण ग्रंथ नहीं लिखा।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"Which of the following is a play written by Kalidasa?","q_hi":"निम्नलिखित में से कौन सा कालिदास द्वारा लिखित नाटक है?","o":["Raghuvamsa","Meghaduta","Abhijnanasakuntalam","Kumarasambhava"],"o_hi":["रघुवंश","मेघदूत","अभिज्ञानशाकुन्तलम्","कुमारसंभव"],"a":2,"exp":"Abhijnanasakuntalam is a famous play (drama) by Kalidasa, while the others are poems.","exp_hi":"अभिज्ञानशाकुन्तलम् कालिदास द्वारा रचित प्रसिद्ध नाटक है, जबकि अन्य काव्य हैं।","why":["रघुवंश एक महाकाव्य है, नाटक नहीं।","मेघदूत एक खण्डकाव्य है, नाटक नहीं।","कुमारसंभव एक महाकाव्य है, नाटक नहीं।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"Who is known as 'Adikavi' (the first poet) in Sanskrit literature?","q_hi":"संस्कृत साहित्य में 'आदिकवि' किसे कहा जाता है?","o":["Kalidasa","Tulsidas","Valmiki","Bhasa"],"o_hi":["कालिदास","तुलसीदास","वाल्मीकि","भास"],"a":2,"exp":"Valmiki is revered as the Adikavi for composing the Ramayana, the first epic poem.","exp_hi":"वाल्मीकि को रामायण की रचना के लिए आदिकवि कहा जाता है, जो पहला महाकाव्य है।","why":["कालिदास को 'कविकुलगुरु' कहा जाता है, आदिकवि नहीं।","तुलसीदास हिंदी के कवि थे, संस्कृत के नहीं।","भास एक नाटककार थे, आदिकवि नहीं।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"Which of the following is the correct order of the four Vedas?","q_hi":"चार वेदों का सही क्रम निम्नलिखित में से कौन सा है?","o":["Rigveda, Yajurveda, Samaveda, Atharvaveda","Samaveda, Rigveda, Yajurveda, Atharvaveda","Rigveda, Samaveda, Yajurveda, Atharvaveda","Yajurveda, Rigveda, Samaveda, Atharvaveda"],"o_hi":["ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद","सामवेद, ऋग्वेद, यजुर्वेद, अथर्ववेद","ऋग्वेद, सामवेद, यजुर्वेद, अथर्ववेद","यजुर्वेद, ऋग्वेद, सामवेद, अथर्ववेद"],"a":0,"exp":"The traditional order is Rigveda, Yajurveda, Samaveda, Atharvaveda.","exp_hi":"पारंपरिक क्रम है ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद।","why":["सामवेद को बाद में रखा जाता है, यह क्रम गलत है।","सामवेद को दूसरे स्थान पर रखना गलत है।","यजुर्वेद को पहले रखना गलत है।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"In Sanskrit grammar, the word 'बालक' (boy) is in which gender?","q_hi":"संस्कृत व्याकरण में 'बालक' शब्द किस लिंग में है?","o":["Feminine","Masculine","Neuter","Common"],"o_hi":["स्त्रीलिंग","पुल्लिंग","नपुंसकलिंग","उभयलिंग"],"a":1,"exp":"'बालक' refers to a male child, hence it is masculine gender (पुल्लिंग).","exp_hi":"'बालक' पुरुष बच्चे के लिए है, इसलिए यह पुल्लिंग है।","why":["स्त्रीलिंग के लिए 'बालिका' शब्द होता है।","नपुंसकलिंग के लिए 'बाल' शब्द होता है।","संस्कृत में उभयलिंग की अवधारणा नहीं है।"],"topic":"Sanskrit Grammar","level":1,"mode":"standard"},{"q":"Which of the following is NOT a work of Kalidasa?","q_hi":"निम्नलिखित में से कौन सी कृति कालिदास की नहीं है?","o":["Raghuvamsa","Meghaduta","Kumarasambhava","Mricchakatika"],"o_hi":["रघुवंश","मेघदूत","कुमारसंभव","मृच्छकटिका"],"a":3,"exp":"Mricchakatika is written by Shudraka, not Kalidasa.","exp_hi":"मृच्छकटिका शूद्रक द्वारा लिखी गई है, कालिदास द्वारा नहीं।","why":["रघुवंश कालिदास का महाकाव्य है।","मेघदूत कालिदास का खण्डकाव्य है।","कुमारसंभव कालिदास का महाकाव्य है।"],"topic":"Sanskrit Literature","level":2,"mode":"standard"}]}]/*__DATA_END__*/);
